return (() => {
  const p1 = $('GIAMA_1').first().json.turnosDisponibles
  const p2 = $('GIAMA_2').first().json.turnosDisponibles
  const allTurnos = [...p1, ...p2];

  function pick(arr) {
    const res = [];
    const days = [...new Set(arr.map(t => t.dia))];

    // 🗓️ Primero intenta tomar uno por día
    while (res.length < 16 && days.length) {
      const d = days.splice(Math.floor(Math.random() * days.length), 1)[0];
      const opts = arr.filter(t => t.dia === d);
      if (opts.length) res.push(opts[Math.floor(Math.random() * opts.length)]);
    }

    // 🕐 Si no llegó a 16, completa con turnos de días ya usados
    while (res.length < 16) {
      const remaining = arr.filter(
        t => !res.some(r => r.dia === t.dia && r.horarioLlegada === t.horarioLlegada)
      );
      if (remaining.length === 0) break;
      res.push(remaining[Math.floor(Math.random() * remaining.length)]);
    }

    // 📦 Formato final con año en fechaFormato
    return res.map(t => {
      // Extraer año de la fecha original si existe
      let fechaConAnio = t.fechaFormato;

      // Si fechaFormato no tiene año, intentar obtenerlo de otros campos
      if (t.fechaFormato && !t.fechaFormato.match(/\d{4}/)) {
        // Si existe un campo fecha completo, extraer el año
        if (t.fecha) {
          const year = new Date(t.fecha).getFullYear();
          fechaConAnio = `${t.fechaFormato}/${year}`;
        } else {
          // Si no, usar el año actual
          fechaConAnio = `${t.fechaFormato}/${new Date().getFullYear()}`;
        }
      }

      return {
        dia: t.dia,
        inicio: t.horarioLlegada,
        final: t.horarioEntrega,
        Id_Calendario: t.Id_Calendario,
        fechaFormato: fechaConAnio
      };
    });
  }

  return [{ json: { turnos: pick(allTurnos) } }];
})();

